import React, { useState } from 'react';
import Navbar from '../components/Navbar';
import { FaPaperPlane, FaUserSecret, FaLock, FaHeart } from 'react-icons/fa';

function AnonymousChat() {
  const [messages, setMessages] = useState([
    { id: 1, text: "Welcome to Anonymous Support Space. Your identity is completely hidden.", isUser: false, time: new Date().toLocaleTimeString() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);

  const getAIResponse = (message) => {
    const msg = message.toLowerCase();
    if (msg.includes('sad') || msg.includes('depressed')) {
      return "I hear you. It's okay to feel sad. You're not alone. 💙";
    }
    if (msg.includes('stress') || msg.includes('overwhelm')) {
      return "That sounds challenging. Take a deep breath. Let's take it one step at a time. 🧘";
    }
    if (msg.includes('exam') || msg.includes('study')) {
      return "Academic pressure is real. Break your study into small chunks. You've got this! 📚";
    }
    if (msg.includes('friend') || msg.includes('lonely')) {
      return "Feeling lonely is tough. Remember that many people care about you. 💕";
    }
    return "Thank you for sharing. Your feelings are valid. I'm here to listen anonymously. 💙";
  };

  const sendMessage = () => {
    if (!input.trim()) return;
    
    const userMessage = { id: Date.now(), text: input, isUser: true, time: new Date().toLocaleTimeString() };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);
    
    setTimeout(() => {
      const aiResponse = { id: Date.now() + 1, text: getAIResponse(input), isUser: false, time: new Date().toLocaleTimeString() };
      setMessages(prev => [...prev, aiResponse]);
      setIsTyping(false);
    }, 800);
  };

  return (
    <div style={styles.container}>
      <Navbar />
      <div style={styles.navSpacer} />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}><FaUserSecret size={20} /> Anonymous Chat</h1>
          <p style={styles.subtitle}>Share freely. Your identity is hidden.</p>
        </div>

        <div style={styles.privacyCard}>
          <FaLock size={12} color="#2ecc71" />
          <span>🔒 100% Anonymous - No personal info stored</span>
        </div>

        <div style={styles.chatContainer}>
          <div style={styles.messagesArea}>
            {messages.map(msg => (
              <div key={msg.id} style={{...styles.message, justifyContent: msg.isUser ? 'flex-end' : 'flex-start'}}>
                <div style={{...styles.messageBubble, background: msg.isUser ? '#667eea' : '#f0f0f0', color: msg.isUser ? 'white' : '#333'}}>
                  <p style={styles.messageText}>{msg.text}</p>
                  <span style={styles.messageTime}>{msg.time}</span>
                </div>
              </div>
            ))}
            {isTyping && (
              <div style={styles.typingIndicator}>
                <div style={styles.typingDot}></div>
                <div style={styles.typingDot}></div>
                <div style={styles.typingDot}></div>
              </div>
            )}
          </div>
          
          <div style={styles.inputArea}>
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
              placeholder="Type your message..."
              style={styles.input}
            />
            <button onClick={sendMessage} style={styles.sendBtn}>
              <FaPaperPlane size={12} />
            </button>
          </div>
        </div>

        <div style={styles.resourcesCard}>
          <FaHeart size={12} color="#e84393" />
          <span>📞 Crisis Helpline: 988 | Text HOME to 741741</span>
        </div>
      </div>
    </div>
  );
}

const styles = {
  container: { 
    minHeight: '100vh', 
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' 
  },
  navSpacer: { 
    height: '52px' 
  },
  content: { 
    maxWidth: '550px', 
    margin: '0 auto', 
    padding: '0 16px 20px 16px' 
  },
  header: { 
    textAlign: 'center', 
    marginBottom: '16px', 
    color: 'white' 
  },
  title: { 
    fontSize: '20px', 
    marginBottom: '4px', 
    display: 'flex', 
    alignItems: 'center', 
    justifyContent: 'center', 
    gap: '8px' 
  },
  subtitle: { 
    fontSize: '11px', 
    opacity: 0.8 
  },
  privacyCard: { 
    background: 'rgba(255,255,255,0.95)', 
    borderRadius: '10px', 
    padding: '8px 12px', 
    marginBottom: '16px', 
    display: 'flex', 
    alignItems: 'center', 
    gap: '8px', 
    fontSize: '11px', 
    fontWeight: '500' 
  },
  chatContainer: { 
    background: 'white', 
    borderRadius: '16px', 
    height: '420px', 
    display: 'flex', 
    flexDirection: 'column', 
    overflow: 'hidden' 
  },
  messagesArea: { 
    flex: 1, 
    overflowY: 'auto', 
    padding: '14px', 
    display: 'flex', 
    flexDirection: 'column', 
    gap: '10px' 
  },
  message: { 
    display: 'flex' 
  },
  messageBubble: { 
    maxWidth: '75%', 
    padding: '8px 12px', 
    borderRadius: '16px' 
  },
  messageText: { 
    margin: 0, 
    fontSize: '12px', 
    lineHeight: 1.4 
  },
  messageTime: { 
    fontSize: '9px', 
    opacity: 0.5, 
    display: 'block', 
    marginTop: '4px' 
  },
  typingIndicator: { 
    display: 'flex', 
    gap: '4px', 
    padding: '8px 12px', 
    background: '#f0f0f0', 
    borderRadius: '16px', 
    width: '40px' 
  },
  typingDot: { 
    width: '6px', 
    height: '6px', 
    background: '#999', 
    borderRadius: '50%', 
    animation: 'bounce 1s infinite' 
  },
  inputArea: { 
    display: 'flex', 
    padding: '12px', 
    gap: '8px', 
    borderTop: '1px solid #e0e0e0' 
  },
  input: { 
    flex: 1, 
    padding: '8px 12px', 
    border: '1px solid #e0e0e0', 
    borderRadius: '20px', 
    outline: 'none', 
    fontSize: '12px' 
  },
  sendBtn: { 
    background: '#667eea', 
    color: 'white', 
    border: 'none', 
    width: '34px', 
    height: '34px', 
    borderRadius: '50%', 
    cursor: 'pointer', 
    display: 'flex', 
    alignItems: 'center', 
    justifyContent: 'center' 
  },
  resourcesCard: { 
    marginTop: '16px', 
    background: 'rgba(255,255,255,0.95)', 
    borderRadius: '10px', 
    padding: '10px', 
    display: 'flex', 
    alignItems: 'center', 
    justifyContent: 'center', 
    gap: '8px', 
    fontSize: '10px',
    color: '#555'
  },
};

// Add animation
const styleSheet = document.createElement("style");
styleSheet.textContent = `
  @keyframes bounce {
    0%, 60%, 100% { transform: translateY(0); }
    30% { transform: translateY(-4px); }
  }
`;
document.head.appendChild(styleSheet);

export default AnonymousChat;
